entries[88907] = { ["name"] = "Fetisch von Hir'eek", ["text"] = "Wirken in 2 sek. 5\nHir'eek ist einer der von den südlichen Trollen verehrten Tiergeister. Hir'eeks Totemtier ist die Fledermaus. Unter Hir'eeks berühmtesten Anhängern befand sich Jeklik, eine Hohepriesterin von Zandalar.\nFetisch von Hir'eek\nWird beim Aufheben gebunden" }
entries[88908] = { ["name"] = "Echsenkrallenglücksbringer", ["text"] = "Wirken in 2 sek. 5\nDer kleine, mumifizierte Fuß einer Dschungelechse. Die einst enthaltene Magie ist längst verflogen.\nEchsenkrallenglücksbringer\nWird beim Aufheben gebunden" }
entries[88909] = { ["name"] = "Hölzerne Trillerpfeife", ["text"] = "Wirken in 2 sek. 5\nDas ist eine kleine Trillerpfeife aus Eichenholz. Sie mag einst dazu gedient haben, ein Haustier oder ein Reittier zu rufen, oder möglicherweise auch als Kinderspielzeug. Jedenfalls hat etwas oder jemand darauf herumgekaut, sei es nun ein Tier oder ein Zwergenkind.\nHölzerne Trillerpfeife\nWird beim Aufheben gebunden" }
entries[88910] = { ["name"] = "Gürtelschnalle mit dem Wappen von Ambossar", ["text"] = "Wirken in 2 sek. 5\nModimus Ambossar war vor dem Krieg der Drei Hämmer der Hochkönig der Zwerge. Noch immer thront seine Statue über dem Tor von Eisenschmiede. Diese Messingschnalle mag einst einem Mitglied seines Hauses oder seiner Dienerschaft gehört haben.\nGürtelschnalle mit dem Wappen von Ambossar\nWird beim Aufheben gebunden" }
