entries[89696] = { ["name"] = "Geweihtragende Umhangspange", ["text"] = "Wirken in 2 sek. 5\nDie Spange ist aus lackiertem Holz gefertigt, das zu einem Hirschgeweih geschnitzt wurde. In die Rückseite ist auf Darnassisch der Name 'Pyramond' eingekerbt.\nGeweihtragende Umhangspange\nWird beim Aufheben gebunden" }
